if(b.dataset.miscChart){const [type,id]=b.dataset.miscChart.split(':');const wrap=b.closest('.consumable-wrap'),chart=wrap?.querySelector('.consumable-chart');if(chart){if(!chart.hidden){chart.hidden=true;return;}chart.innerHTML='<div class="loading">LOADING PRICE HISTORY…</div>';chart.hidden=false;try{const data=await api(`consumable-history?type=${encodeURIComponent(type)}&id=${encodeURIComponent(id)}&platform=${marketPlatform}&hours=168`);chart.innerHTML=data.history.length>1?interactiveChart(data.history):empty('Not enough history yet.','The chart appears after more price observations.');}catch(error){chart.innerHTML=empty('Chart unavailable.',esc(error.message));}}return;}
