$$('[data-market-platform]').forEach(b=>b.onclick=async()=>{if(marketPlatform===b.dataset.marketPlatform)return;marketPlatform=b.dataset.marketPlatform;me.platform=marketPlatform;localStorage.setItem('futbot-platform',marketPlatform);if(page==='players'&&selected)selectedPlatform=marketPlatform;await refresh();await render();});const moverSelect=$('#mover-rarity');if(moverSelect)moverSelect.onchange=async()=>{moverRarity=moverSelect.value;await refresh();await render();};const raritySelect=$('#rarity-filter'),ratingSelect=$('#rating-filter'),positionSelect=$('#position-filter');if(raritySelect)raritySelect.onchange=()=>{playerRarity=raritySelect.value;$('#player-search').dispatchEvent(new Event('input'));};if(ratingSelect)ratingSelect.onchange=()=>{playerRating=ratingSelect.value;$('#player-search').dispatchEvent(new Event('input'));};if(positionSelect)positionSelect.onchange=()=>{playerPosition=positionSelect.value;$('#player-search').dispatchEvent(new Event('input'));};$('#guild').onchange=async()=>{guild=$('#guild').value;$('#admin-nav').hidden=!guild;$('#workspace-title').textContent=$('#guild').selectedOptions[0].textContent;if(adminPages.includes(page)&&!guild)page='overview';await render();};
$('#mobile-menu').onclick=()=>$('.sidebar').classList.toggle('open');$('#refresh').onclick=()=>busy($('#refresh'),async()=>{await refresh();await render();toast('Data refreshed. Market cache lasts up to five minutes.');});$('#logout').onclick=()=>busy($('#logout'),async()=>{await post('logout');location.assign('/app/');});
async function boot(){try{me=await api('me');$('#content-watch-nav').hidden=!me.contentWatchOperator;marketPlatform=localStorage.getItem('futbot-platform')||me.platform||'ps5';me.platform=marketPlatform;csrf=me.csrf;$('#login').hidden=true;$('#shell').hidden=false;$('#username').textContent=me.user.name;if(me.user.avatar){$('#avatar').src=me.user.avatar;$('#avatar').hidden=false;}await refresh();await render();const params=new URLSearchParams(location.search);if(params.has('billing')||params.has('plan')){page='billing';await render();toast(params.get('billing')==='success'?'Checkout returned. Benefits activate after payment verification.':'Billing updated.');history.replaceState(null,'','/app/');}try{const data=await api('guilds');$('#guild').querySelectorAll('option:not(:first-child)').forEach(o=>o.remove());for(const g of data.guilds){const o=document.createElement('option');o.value=g.id;o.textContent=g.name;$('#guild').append(o);}}catch(e){toast('Server list: '+e.message);}}catch(e){if(me){$('#shell').hidden=false;$('#login').hidden=true;$('#main').innerHTML=`<div class="error"><h2>Data is temporarily unavailable.</h2><p>${esc(e.message)}</p><button class="button" id="boot-retry">Reconnect ↻</button></div>`;$('#boot-retry').onclick=boot;}else{$('#login').hidden=false;$('#shell').hidden=true;}}}
function sparkline(history){const points=history.map(p=>({t:new Date(p.at).getTime(),v:Number(p.value)})).filter(p=>Number.isFinite(p.t)&&Number.isFinite(p.v)&&p.v>0);if(points.length<2)return '<div class="spark-empty">More history needed</div>';const min=Math.min(...points.map(p=>p.v)),max=Math.max(...points.map(p=>p.v)),start=points[0].t,end=points.at(-1).t;const coords=points.map(p=>`${8+(p.t-start)/Math.max(1,end-start)*304},${68-(p.v-min)/Math.max(1,max-min)*56}`).join(' ');return `<svg viewBox="0 0 320 80" role="img" aria-label="24-hour hourly median price trend"><path d="M8 70H312" stroke="#b9c3cb"/><polyline points="${coords}" fill="none" stroke="${points.at(-1).v>=points[0].v?'#3458ff':'#e45b19'}" stroke-width="2.5" vector-effect="non-scaling-stroke"/></svg>`;}
function updateFodderTarget(){const f=$('#fodder-alert-form');if(!f)return;const r=Number(f.elements.rating.value),index=Number(market?.fodderIndices?.find(x=>x.rating===r)?.value),drop=Number(f.elements.dropPercent.value);$('#fodder-target-preview').textContent=index&&drop?`Current 3-card index: ${fmt(index)} coins · alert at about ${fmt(Math.floor(index*(1-drop/100)))} coins`: 'Waiting for three fresh cards at this rating.';}
function selectedOptions(items,value,label='name'){return items.map(c=>`<option value="${esc(c.id)}" ${String(c.id)===String(value)?'selected':''}>${esc(c[label])}</option>`).join('');}
