 if(page==='community'){const data=await api('communities');if(!communityGuild&&data.guilds?.length)communityGuild=data.guilds[0].id;let lists=[],plan='';if(communityGuild){try{const d=await api(`communities/${communityGuild}/lists`);lists=d.lists;plan=d.plan;}catch(e){plan=e.message;}}return heading('YOUR COMMUNITY / SHARED RESEARCH','THE CLUB SHORTLIST.','Follow your server’s selected cards. Your own watchlist and targets stay private.')+`<div class="panel form-panel"><div class="form-grid"><label>Server<select id="community-guild"><option value="">Choose your server</option>${selectedOptions(data.guilds??[],communityGuild)}</select></label><label>Shared list<select id="community-list"><option value="">Choose a list</option>${selectedOptions(lists,communityList)}</select></label></div><div class="split-note"><p class="hint">${esc(plan)} · Complete members can claim an available Pro seat if their roles qualify.</p><button class="button small" id="claim-seat" ${communityGuild?'':'disabled'}>Claim included Pro ↗</button></div></div><section class="panel" style="margin-top:20px" id="community-cards">${empty('Pick a shared list.','Cards from your community appear here with your own alert and watch controls.')}</section>`;}
