function feedFormData(){const f=$('#feed-form');return {id:f.elements.id.value||undefined,name:f.elements.name.value,kind:f.elements.kind.value,channel_id:f.elements.channel_id.value,role_id:f.elements.role_id.value,list_id:f.elements.list_id.value,times:f.elements.times.value.split(',').map(t=>t.trim()).filter(Boolean),timezone:f.elements.timezone.value,enabled:f.elements.enabled.checked};}
function fillFeed(f){const form=$('#feed-form');for(const name of ['id','name','kind','channel_id','role_id','list_id','timezone'])form.elements[name].value=f[name]??'';form.elements.times.value=f.times.join(', ');form.elements.enabled.checked=f.enabled;$('#feed-editor-title').textContent='Edit '+f.name;form.scrollIntoView?.({behavior:'smooth',block:'start'});}
async function openShared(list){const d=await post(`communities/${guild}/cards`,{list});$('#shared-detail').innerHTML=`<h3 style="margin-top:20px">Current fresh-priced cards</h3>${d.cards.map(c=>`<div class="list-choice"><span>${esc(c.name)} · ${fmt(c.value)}</span><button class="icon-button" data-shared-remove="${c.id}" data-list="${list}">×</button></div>`).join('')||'<p class="hint">No fresh-priced cards. Saved cards remain in the list.</p>'}`;}
function bindExtension(){
 const f=$('#feed-form');if(f)f.onsubmit=async e=>{e.preventDefault();await busy(f.querySelector('[type=submit]')??f.querySelector('button:last-child'),async()=>{await post(`guilds/${guild}/feeds`,feedFormData());await render();toast('Feed saved. The bot scheduler checks once a minute.');});};
 const af=$('#access-form');if(af)af.onsubmit=async e=>{e.preventDefault();await busy(af.querySelector('button'),async()=>{await post(`guilds/${guild}/settings`,{...brand,settings:{...brand.settings,accessRoleIds:[...af.querySelectorAll('input:checked')].map(i=>i.value)}},'PUT');toast('Member eligibility saved.');});};
 const lf=$('#list-form');if(lf)lf.onsubmit=async e=>{e.preventDefault();await busy(lf.querySelector('button'),async()=>{await post(`guilds/${guild}/shared`,{name:lf.elements.name.value});await render();toast('Shared list created.');});};
 const cf=$('#shared-card-form');if(cf)cf.onsubmit=async e=>{e.preventDefault();await busy(cf.querySelector('button'),async()=>{await post(`guilds/${guild}/shared`,{list:cf.elements.list.value,card:cf.elements.card.value});await openShared(cf.elements.list.value);toast('Card added to shared list.');});};
 const cg=$('#community-guild');if(cg)cg.onchange=async()=>{communityGuild=cg.value;communityList='';await render();};
 const cl=$('#community-list');if(cl)cl.onchange=async()=>{communityList=cl.value;if(!communityList)return;try{const d=await post(`communities/${communityGuild}/cards`,{list:communityList});$('#community-cards').innerHTML=table(d.cards);}catch(e){toast(e.message);}};
}
async function extensionClick(b){
 if(b.id==='new-feed'){$('#feed-form').reset();$('#feed-form').elements.id.value='';$('#feed-editor-title').textContent='New automatic feed';return true;}
 if(b.dataset.feedEdit){fillFeed(feedData.find(f=>String(f.id)===b.dataset.feedEdit));return true;}
 if(b.dataset.feedToggle){await busy(b,async()=>{const f=feedData.find(f=>String(f.id)===b.dataset.feedToggle);await post(`guilds/${guild}/feeds`,{...f,enabled:!f.enabled});await render();});return true;}
 if(b.dataset.feedDelete){await busy(b,async()=>{await post(`guilds/${guild}/feeds`,{id:b.dataset.feedDelete},'DELETE');await render();});return true;}
 if(b.id==='preview-feed'){await busy(b,async()=>{const data=await post(`guilds/${guild}/feed-preview`,feedFormData()),e=data.payload.embeds[0];$('#scheduled-preview').innerHTML=`<div class="discord-meta"><span class="bot-icon">F</span><b>${esc(e.author.name)}</b><span class="app-tag">APP</span><small>preview</small></div><div class="discord-embed" style="border-color:#${e.color.toString(16).padStart(6,'0')}"><h3>${esc(e.title)}</h3><p>${esc(feedFormData().name)} · ${esc(me.platform.toUpperCase())}</p><div class="preview-players">${data.cards.slice(0,9).map(c=>`<div>${img(c,true)}<span><b>${esc(c.name)}</b><small>${esc(c.rating)} ${esc(c.position)}</small><strong>${fmt(c.value)} 🪙</strong></span></div>`).join('')}</div>${data.hasImage?`<img src="/api/guilds/${guild}/feed-image" alt="Current branded fodder board">`:''}<footer>${esc(e.footer.text)}</footer></div><p class="hint">Next scheduled slot: ${new Date(data.nextRun).toLocaleString('en-GB')}. Preview only; nothing has been posted.</p>`;});return true;}
 if(b.dataset.sharedOpen){await busy(b,()=>openShared(b.dataset.sharedOpen));return true;}
 if(b.dataset.listDelete){await busy(b,async()=>{await post(`guilds/${guild}/shared`,{list:b.dataset.listDelete},'DELETE');await render();});return true;}
 if(b.dataset.sharedRemove){await busy(b,async()=>{await post(`guilds/${guild}/shared`,{list:b.dataset.list,card:b.dataset.sharedRemove},'DELETE');await openShared(b.dataset.list);});return true;}
 if(b.dataset.releaseSeat){await busy(b,async()=>{await post(`guilds/${guild}/seats`,{user:b.dataset.releaseSeat},'DELETE');await render();toast('Seat released.');});return true;}
 if(b.id==='claim-seat'){await busy(b,async()=>{await post(`communities/${communityGuild}/claim`);me=await api('me');await render();toast('Pro seat claimed. Your new limits are active.');});return true;}
 if(b.dataset.checkout){await busy(b,async()=>{const data=await post('billing/checkout',{plan:b.dataset.checkout,...(b.dataset.checkout==='personal'?{}:{guild})});location.assign(data.url);});return true;}
 if(b.dataset.portal){await busy(b,async()=>{const data=await post('billing/portal',b.dataset.portal==='server'?{guild}:{});location.assign(data.url);});return true;}
 return false;
}
setInterval(async()=>{if(!me||document.hidden||refreshing||$('#alert-dialog').open||document.activeElement?.matches('input,select,textarea')||!['alerts','watchlist','overview'].includes(page))return;refreshing=true;try{const next=await api('me');me={...next,platform:marketPlatform};await refresh();await render();}catch(e){toast(e.message);}finally{refreshing=false;}},60000);
boot();
